async function chamarComTimeout(url, opcoes, ms = 5000) {
  const controle = new AbortController()
  const relogio = setTimeout(() => controle.abort(), ms)
  try {
    return await fetch(url, { ...opcoes, signal: controle.signal })
  } finally {
    clearTimeout(relogio)
  }
}

async function comRetentativa(operacao, tentativas = 3) {
  for (let numero = 1; numero <= tentativas; numero += 1) {
    try {
      return await operacao()
    } catch (erro) {
      const ultima = numero === tentativas
      if (ultima || !transitorio(erro)) throw erro
      await esperar(numero * 1000)   // 1s, 2s
    }
  }
}

