function responder(requisicao, recurso) {
  // Vale para os dois caminhos: dado de usuário nunca pode ser public.
  const cacheControl = recurso.privado ? 'private, no-cache' : 'public, max-age=300'

  // O cliente diz qual versão tem; se for a atual, não há o que enviar.
  if (requisicao.ifNoneMatch === recurso.etag) {
    return { status: 304, etag: recurso.etag, cacheControl }
  }

  return { status: 200, corpo: recurso.corpo, etag: recurso.etag, cacheControl }
}

