exercise.solution:
function aceitar(token, agora, papelNecessario) {
  // Sem assinatura válida, o resto do token é texto que o cliente escreveu:
  // analisar exp ou papel antes disso seria confiar em dado não verificado.
  if (!token.assinaturaValida) return { ok: false, motivo: 'assinatura' }

  if (token.exp <= agora) return { ok: false, motivo: 'expirado' }

  if (token.papel !== papelNecessario) return { ok: false, motivo: 'papel' }

  return { ok: true }
}

