const STATUS_POR_CODIGO = {
  nao_encontrado: 404,
  nao_autenticado: 401,
  sem_permissao: 403,
  validacao: 422,
  limite_excedido: 429,
}

function statusDoErro(codigo) {
  // Erro que o servidor não classificou é erro do servidor.
  return STATUS_POR_CODIGO[codigo] ?? 500
}

function deveRepetir(status) {
  // Lista explícita em vez de faixa: 501 ficaria dentro de "5xx" e não se repete.
  return [429, 500, 502, 503, 504].includes(status)
}
